import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosPasswordInput, KozmosThemeProvider } from "../../index";

/**
 * Vue's PasswordInput: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port PasswordInput`; RightToLeft drawn by hand, in
 * a right-to-left KozmosThemeProvider as React's is.
 */
type Args = Record<string, unknown>;

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/PasswordInput",
  component: KozmosPasswordInput,
  args: {
    label: "Password",
    placeholder: "Enter password",
    helperText: "Use at least 12 characters.",
  },
  render: (args) => ({
    setup: () => () => h(KozmosPasswordInput, args),
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {};

export const Visible: Story = {
  args: {
    defaultValue: "CorrectHorseBatteryStaple",
    defaultVisible: true,
  },
};

export const Error: Story = {
  args: {
    error: "Password is required.",
  },
};

export const WithoutToggle: Story = {
  args: {
    showToggle: false,
  },
};

export const RightToLeft: Story = {
  render: (args, { globals }) => ({
    setup: () => () =>
      h(
        KozmosThemeProvider,
        { dir: "rtl", theme: globals?.theme === "dark" ? "dark" : "light" },
        () => [
          h("div", { style: { width: "220px" } }, [
            h(KozmosPasswordInput, args),
          ]),
        ],
      ),
  }),
};
